variables.issue_message:
{% set grace = {'climate.entity_001': 1200, 'binary_sensor.entity_009': 900, 'binary_sensor.entity_011': 900, 'binary_sensor.entity_010': 900} %}
{% set explicit = ['binary_sensor.entity_006','binary_sensor.entity_009','binary_sensor.entity_011','binary_sensor.entity_010'] %}
{% set monitored = (label_entities('label_002') + explicit) | unique | list %}
{% set unavailable = label_entities('label_001') %}
{% set ns = namespace(lines=[]) %}
{% for e in monitored %}
  {% if (e in unavailable or e in explicit) and states(e) in ['unavailable','unknown'] %}
    {% set age = (now() - states[e].last_changed).total_seconds() if states[e] is not none else 999999 %}
    {% if age >= grace.get(e, 0) %}
      {% set ns.lines = ns.lines + ['- ' ~ entity_name(e) ~ ' is ' ~ states(e) ~ ' for ' ~ ((age/60)|round(0)|int) ~ 'm (' ~ e ~ ')'] %}
    {% endif %}
  {% endif %}
{% endfor %}
{% if states('group.object_001') in ['unavailable','unknown'] %}
  {% set ns.lines = ns.lines + ['- Family group is ' ~ states('group.object_001') ~ ' (group.object_001)'] %}
{% endif %}
{{ ns.lines | join('\n') }}

